 84		\[
 85			\hat{S}^X_g = \sum_{g_Z} \hat{S}_{g,g_Z}
 86			\qquad \text{and} \qquad
 87			\hat{S}^Z_g = \sum_{g_X} \hat{S}_{g_X,g}\;,
 88		\]
