1219		\label{lem:restricted-line-mixture-bounds}
1220		\lean{MIPStarRE.QPBT.linePointDist_eq_mixture_restricted}
1221		\lean{MIPStarRE.QPBT.avg_restricted_le, MIPStarRE.QPBT.avg_restricted_prod_le}
